import{_ as a,o as r,c as i,ac as t}from"./chunks/framework.CrIZQWiq.js";const g=JSON.parse('{"title":"LeebApi：把 Swagger 文档一键变成 TypeScript / JavaScript 代码","description":"","frontmatter":{},"headers":[],"relativePath":"articles/产品/leebapi-intro.md","filePath":"articles/产品/leebapi-intro.md","lastUpdated":1781310943000}'),l={name:"articles/产品/leebapi-intro.md"};function o(c,e,d,n,p,s){return r(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1781310943000"},e[0]||(e[0]=[t('<h1 id="leebapi-把-swagger-文档一键变成-typescript-javascript-代码" tabindex="-1">LeebApi：把 Swagger 文档一键变成 TypeScript / JavaScript 代码 <a class="header-anchor" href="#leebapi-把-swagger-文档一键变成-typescript-javascript-代码" aria-label="Permalink to &quot;LeebApi：把 Swagger 文档一键变成 TypeScript / JavaScript 代码&quot;">​</a></h1><blockquote><p>后端接口文档更新了，前端类型却还在手写？LeebApi 让你告别重复劳动。</p></blockquote><hr><h2 id="一句话介绍" tabindex="-1">一句话介绍 <a class="header-anchor" href="#一句话介绍" aria-label="Permalink to &quot;一句话介绍&quot;">​</a></h2><p><strong>LeebApi</strong> 是一款 VS Code 插件，能够基于 Swagger / OpenAPI 文档自动生成 TypeScript 或 JavaScript 的接口类型定义与请求配置代码。</p><hr><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><ul><li><strong>VS Code Marketplace</strong>：<a href="https://marketplace.visualstudio.com/items?itemName=leeb.leeb-api" target="_blank" rel="noreferrer">https://marketplace.visualstudio.com/items?itemName=leeb.leeb-api</a></li><li><strong>一键安装</strong>（需本地已安装 VS Code）：<a href="vscode:extension/leeb.leeb-api" target="_blank" rel="noreferrer">vscode:extension/leeb.leeb-api</a></li></ul><hr><h2 id="为什么需要它" tabindex="-1">为什么需要它？ <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它？&quot;">​</a></h2><p>在前后端分离的项目里，前端开发者最熟悉这样的场景：</p><ul><li>打开 Swagger UI，对照每个接口手写 <code>interface</code>；</li><li>手动拼接 URL、method、path 参数、query 参数、请求体；</li><li>后端文档一更新，前端类型就过时，导致运行时才发现字段对不上；</li><li>项目越大，接口越多，这种重复劳动越让人崩溃。</li></ul><p>LeebApi 的目的很简单：<strong>让机器接管这部分机械工作</strong>，你只需要专注于业务逻辑。</p><hr><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><h3 id="🎨-可视化生成面板" tabindex="-1">🎨 可视化生成面板 <a class="header-anchor" href="#🎨-可视化生成面板" aria-label="Permalink to &quot;🎨 可视化生成面板&quot;">​</a></h3><p>点击 VS Code 左侧活动栏的 <code>&lt;/&gt;</code> 图标，即可打开 LeebApi 的 Webview 面板，无需离开编辑器。</p><h3 id="🔗-支持两种输入方式" tabindex="-1">🔗 支持两种输入方式 <a class="header-anchor" href="#🔗-支持两种输入方式" aria-label="Permalink to &quot;🔗 支持两种输入方式&quot;">​</a></h3><ul><li><strong>Swagger URL</strong>：直接填入后端暴露的 Swagger JSON 地址；</li><li><strong>JSON 内容</strong>：也可以把 Swagger JSON 直接粘贴进面板。</li></ul><h3 id="📝-typescript-javascript-双输出" tabindex="-1">📝 TypeScript / JavaScript 双输出 <a class="header-anchor" href="#📝-typescript-javascript-双输出" aria-label="Permalink to &quot;📝 TypeScript / JavaScript 双输出&quot;">​</a></h3><p>根据项目需要选择输出语言：</p><ul><li><strong>TypeScript</strong>：生成完整类型定义，支持接口继承、枚举、数组、对象等复杂结构；</li><li><strong>JavaScript</strong>：生成带 JSDoc 注释的类型提示版本。</li></ul><h3 id="📁-自动生成两个文件" tabindex="-1">📁 自动生成两个文件 <a class="header-anchor" href="#📁-自动生成两个文件" aria-label="Permalink to &quot;📁 自动生成两个文件&quot;">​</a></h3><p>以你设置的前缀命名，例如 <code>swagger-api</code>：</p><ul><li><code>swagger-api.types.ts</code>：实体类型定义（interface / typedef）；</li><li><code>swagger-api.api.ts</code>：接口请求配置，包含 method、url、pathParams、queryParams、body、headers、response 等完整信息。</li></ul><h3 id="🔧-贴心的辅助函数" tabindex="-1">🔧 贴心的辅助函数 <a class="header-anchor" href="#🔧-贴心的辅助函数" aria-label="Permalink to &quot;🔧 贴心的辅助函数&quot;">​</a></h3><p>自动生成 <code>fillPath</code> 和 <code>buildQuery</code> 等工具函数，处理路径参数填充和查询字符串拼接。</p><h3 id="🔄-兼容-swagger-2-0-与-openapi-3-x" tabindex="-1">🔄 兼容 Swagger 2.0 与 OpenAPI 3.x <a class="header-anchor" href="#🔄-兼容-swagger-2-0-与-openapi-3-x" aria-label="Permalink to &quot;🔄 兼容 Swagger 2.0 与 OpenAPI 3.x&quot;">​</a></h3><p>支持 <code>$ref</code>、<code>components/schemas</code>、<code>requestBody.content</code> 等常见结构，不用纠结后端用的是什么版本。</p><h3 id="👀-预览-一键保存" tabindex="-1">👀 预览 + 一键保存 <a class="header-anchor" href="#👀-预览-一键保存" aria-label="Permalink to &quot;👀 预览 + 一键保存&quot;">​</a></h3><p>生成结果可先预览，满意后再保存到项目目录，或分别复制类型 / 接口代码到剪贴板。</p><h3 id="⚙️-可配置默认值" tabindex="-1">⚙️ 可配置默认值 <a class="header-anchor" href="#⚙️-可配置默认值" aria-label="Permalink to &quot;⚙️ 可配置默认值&quot;">​</a></h3><p>支持在 VS Code 设置中配置默认 Swagger URL 和输出前缀：</p><ul><li><code>leebApi.defaultSwaggerUrl</code></li><li><code>leebApi.defaultOutputPrefix</code></li></ul><hr><h2 id="使用流程" tabindex="-1">使用流程 <a class="header-anchor" href="#使用流程" aria-label="Permalink to &quot;使用流程&quot;">​</a></h2><ol><li>点击左侧活动栏的 LeebApi 图标；</li><li>选择「URL 地址」或「JSON 内容」模式输入 Swagger 文档；</li><li>选择输出语言：TypeScript 或 JavaScript；</li><li>选择保存目录，设置文件名前缀（默认 <code>swagger-api</code>）；</li><li>点击「生成预览」，查看类型定义与接口请求代码；</li><li>点击「保存到文件」或分别「复制类型 / 复制接口」。</li></ol><hr><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><ul><li><strong>自研 Swagger / OpenAPI 解析器</strong>，不依赖外部代码生成库，轻量可控；</li><li><strong>递归 JSON Schema 转 TS 类型</strong>，支持 <code>enum</code>、<code>array</code>、<code>object</code>、<code>additionalProperties</code>、<code>date-time</code>、<code>binary</code> 等；</li><li><strong>自动提取接口要素</strong>：路径参数、查询参数、请求体、表单、请求头、响应类型；</li><li><strong>Webview 与 Extension 双向通信</strong>，并配置了 <code>Content-Security-Policy</code>；</li><li><strong>生成的 API 配置使用 <code>as const</code> 断言</strong>，方法名与 URL 都能获得字面量类型推导。</li></ul><hr><h2 id="适合谁用" tabindex="-1">适合谁用？ <a class="header-anchor" href="#适合谁用" aria-label="Permalink to &quot;适合谁用？&quot;">​</a></h2><ul><li>前端工程师、全栈开发者；</li><li>需要快速把 Swagger 文档落地为代码的 TS/JS 项目团队；</li><li>任何基于 RESTful API 的项目，例如 Vue、React、Node 后端 SDK 等。</li></ul><hr><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to &quot;典型场景&quot;">​</a></h2><ul><li>项目初始化时批量生成后端接口代码；</li><li>Swagger 文档更新后快速同步前端类型与请求配置；</li><li>统一团队接口请求规范，减少手写类型错误。</li></ul><hr><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>LeebApi 不是想替代你的手写代码，而是想帮你把最枯燥、最容易出错的部分自动化。让文档真正变成代码，让前后端协作更顺畅。</p><p>如果你也在为 Swagger 文档和前端类型之间的鸿沟头疼，不妨试试 LeebApi。</p><blockquote><p>👉 <a href="https://marketplace.visualstudio.com/items?itemName=leeb.leeb-api" target="_blank" rel="noreferrer">点击前往 VS Code Marketplace 下载 LeebApi</a></p></blockquote>',51)]))}const u=a(l,[["render",o]]);export{g as __pageData,u as default};
